   "title": "三部门发文扩大消费贷贴息：信用卡分期纳入、贴息上限由3000元提至5000元、8月1日起施行",
   "summary": "财政部、央行、金融监管总局印发《关于进一步做好财政金融协同促内需政策有关工作的通知》（财金〔2026〕71号），将信用卡专项/消费/预借现金分期纳入个人消费贷财政贴息，贴息比例年化1个百分点，单人累计贴息上限由每年3000元提至5000元，自2026年8月1日起施行。",
   "decision": "贴息扩围直接利好消费金融与信用卡分期业务，招联「好期贷/信用付」客群融资成本下降，可借势优化获客与定价策略。",
   "source": "中国政府网",
   "url": "https://www.gov.cn/zhengce/zhengceku/202608/content_7078798.htm",
   "firstSeen": "2026-08-21",
