   "summary": "最新贷款市场报价利率出炉，1年期LPR为3.00%、5年期以上LPR为3.50%，连续第15个月维持不变。全国新发放房贷加权均价约3.1%，首套商贷普遍3.05%—3.45%。",
   "decision": "LPR持稳利于消费金融定价预期管理；招联可借低利率窗口优化资金成本，但须同步满足综合融资成本明示的合规要求。",
