   "title": "前7月居民贷款同比多减1.5万亿 住房贷连续13季负增长",
   "summary": "2026年前7个月居民贷款同比多减1.5万亿元，受提前还贷与购房加杠杆低迷影响，住房贷款余额增速已连续13个季度负增长，居民降杠杆趋势短期延续。",
   "decision": "居民去杠杆压制消费信贷需求，关注招联资产规模增长与风险定价的平衡。",
