   "summary": "财新获悉监管部门正酝酿助贷监管指导政策为2025年10月新规“打补丁”，拟要求助贷平台分润不超贷款利息收入20%、单家银行合作助贷平台不超10家，并限制银行自营及理财资金投资消费信贷ABS和非标；信托资金亦在逐步退出助贷。",
   "decision": "关注助贷资金来源收紧与分润上限对招联联合贷/渠道合作模式及消金行业定价的影响。",
