   "title": "三家消金披露中期业绩：头部剧烈收缩，黑马南银法巴逆势扩张",
   "summary": "招联总资产1473.56亿降11.89%、净利降8.18%；中银消金净利增99.33%；南银法巴总资产664.34亿增12.44%、净利增22.38%，自营线下模式+母行协同支撑扩张，助贷名单已大幅缩减。",
