   "summary": "《个人贷款业务明示综合融资成本规定》8月1日施行，招联、蚂蚁、马上等主要消金公司已完成系统改造并公示；招联正常履约情形年化利率4.56%—24%，行业转向价格显性竞争。",
   "decision": "招联息费透明合规已落地，关注其对客户信任与联通渠道联合营销的加分效应。",
