   "title": "消金公司密集调整：增资、配高管、砍助贷、剥离不良",
   "summary": "行业步入风险出清期，中银消金上半年挂牌不良117.44亿元居首，招联挂牌10个包合计106.29亿元居第二，蚂蚁64.78亿元第三。分析称从拼规模转向拼健康，增资补血、渠道瘦身、不良出清成共同选择。",
   "decision": "招联不良出清规模居行业第二，反映存量资产质量压力；代理商侧应严控新增客群质量、配合资产回收节奏，勿盲目冲量。",
