   "title": "招联消费金融发布个人消费贷款贴息政策客户问答",
   "summary": "招联就个人消费贷款贴息政策发布客户问答：2025年9月1日至2026年8月31日期间符合条件的消费可享年化1%贴息，单人累计上限3000元（对应消费30万元），贴息在结息时直接扣减。",
