   "title": "个贷息费亮出明白清单，中邮、招联等消金公司加速公示综合成本",
   "summary": "《金融时报》报道，中邮、招联、蚂蚁、小米等多家消金公司已官网公布个人贷款明示综合融资成本，招联公布正常履约年化利率区间4.56%—24%。消金公司个人贷款年化成本整体在24%以内，部分机构上限从24%下调至20%。",
