   "summary": "8月24日小鹏集团旗下人形机器人业务鹏行宣布完成首轮外部融资超9亿美元，投后估值超63亿美元，创中国具身智能行业单轮私募最高纪录。IDG资本领投，腾讯、阿里巴巴作为战略投资者加入，资金用于研发与量产，IRON机器人计划2026年底前进入量产。",
   "decision": "具身智能资本热度印证AI基础设施与机器人赛道确定性，招联可关注AI在客服、贷后管理等金融场景的替代与增效空间。",
