   "summary": "针对雀巢婴配乳粉因供应商ARA油脂原料检出蜡样芽胞杆菌呕吐毒素（Cereulide）预防性召回，国务院食安办、市场监管总局督促雀巢(中国)完成中国大陆特定批次召回；我国尚未发现相关确诊病例，已部署各地强化婴配乳粉质量安全管控。",
   "decision": "临近预产期(8/25)，务必核对家中待产/囤的奶粉批次是否在召回清单；国行版启赋、S26铂臻、超启能恩及特医奶粉不受影响，但仍需按罐底批号自查。",
