   "title": "全国生育友好城市、生育友好单位创建启动，每周期命名地级不超10个",
   "summary": "国家卫健委启动全国生育友好城市、生育友好单位创建，每3年为一周期，每周期命名全国生育友好城市（地市级）不超10个、县级不超30个、全国生育友好单位不超200个，推动完善生育支持政策体系。",
   "decision": "[关联育儿]生育友好型社会建设提速，住房、教育、医疗向多子女家庭倾斜；可关注所在城市是否入选及配套支持政策。",
