   "summary": "潜江市政府答复人大代表建议，对2024年1月4日后出生且户籍在本市的新生儿，二孩一次性补贴2000元、三孩及以上1万元，2025年已拨付275.8万元；并实施购房奖补（一孩200元/㎡、二孩500元/㎡、三孩800元/㎡），2026年预算安排育儿补贴资金3623.47万元。",
   "decision": "多地生育支持加码（现金+购房奖补），可关注户籍地与工作地政策叠加可能，为宝宝出生后的养育与住房成本提前规划。",
