   "summary": "全国31个省区市及新疆兵团均已将适宜辅助生殖项目纳入医保报销，政策落地一年多来有效降低不孕家庭负担；2026上半年辅助生殖各项目累计170.96万人次，直接费用29.7亿元，医保基金累计支出超19亿元。",
   "decision": "辅助生殖医保减负明确，关联家庭生育财务测算与预产期前后保障安排。",
