   "title": "财政部：今年民生资金12.4万亿、新增政府债券11.89万亿创历年最大",
   "summary": "国新办8月21日发布会上，财政部副部长廖岷给出三组数据：今年财政支出预算首次超30万亿元，新增政府债券规模达11.89万亿元为历年最大，中央对地方转移支付连续第四年超10万亿元、达10.42万亿元。",
   "decision": "积极财政力度空前，对应国常会「大财政」背景；消费与基建托底政策密集，招联需研判居民部门信用修复节奏。",
   "source": "网易",
