   "title": "商务部等9部门印发意见 18条举措激发下沉市场活力活跃县域消费",
   "summary": "商务部、发改委、财政部等9部门联合印发《关于进一步激发下沉市场活力 活跃县域消费的意见》，从渠道升级、业态创新、供给优化等提出18条举措，目前每天超1亿件包裹进出农村。",
   "decision": "县域消费政策利好招联下沉获客与联通渠道协同，关注配套金融服务落地。",
