   "title": "国务院修改《住房公积金管理条例》公布 9月20日起施行",
   "summary": "国务院总理李强签署国务院令公布《关于修改〈住房公积金管理条例〉的决定》，共20条，9月20日起施行：租房提取不再设收入门槛、新增装修/交物业费提取、灵活就业人员可自愿缴存、推动异地贷款便捷办理。",
   "decision": "公积金提取范围放宽，关联家庭住房与生育财务规划，关注对招联家装/消费分期场景的带动。",
   "source": "新华社/人民日报",
