   "overseas": false,
   "title": "国务院修改《住房公积金管理条例》，9月20日起施行",
   "summary": "李强签署国务院令公布修改决定，提取情形由6种扩至9种，租房提取不再设收入比例门槛，新增装修、缴物业费可提取；扩大覆盖面，个体工商户、非全日制及灵活就业人员可自愿缴存；强化风险防控与信用记录。",
   "decision": "公积金覆盖灵活就业2亿+人群并可与消费贷联动，招联可关注新市民/灵活就业客群的住房消费金融场景。",
   "source": "新华社/宁夏长安网",
