   "title": "北京新增20款生成式AI服务备案 累计达279款",
   "summary": "根据《生成式人工智能服务管理暂行办法》，截至8月19日北京市新增20款已完成备案的生成式人工智能服务，累计已完成279款生成式人工智能服务备案。",
