   "impact": "mid",
   "related": true,
   "overseas": false,
   "title": "网络数据安全新规今起施行，公安部就实施答记者问",
   "summary": "公安部明确将依托等级保护备案建立动态监管台账，对重要数据处理者评估报告真实性核验；拒不整改或危害国家安全的可责令停止处理重要数据，第三方评估机构违规也将被处理。",
   "decision": "监管从备案到动态核验趋严，招联数据治理团队须建立报告编制-报送-检查闭环，避免踩红线。",
