   "related": false,
   "overseas": false,
   "title": "司法部：认定欧盟《外国补贴条例》对京东调查构成不当域外管辖",
   "summary": "司法部发布公告，认定欧盟利用其《外国补贴条例》在对京东调查中对中国实体采取的相关跨境调查做法构成不当域外管辖措施，希望欧方立即纠正，否则中方将坚决依法反制。",
   "decision": "中欧监管摩擦加剧，关注招联跨境数据与联通海外合作的法律风险。",
