   "time": "19:30",
   "impact": "mid",
   "related": false,
   "overseas": false,
   "title": "外交部：坚决反对在人工智能问题上搞选边站队、阵营对抗",
   "summary": "就美方拟要求多国在人工智能领域“选边站队”，外交部发言人表示中方坚决反对在人工智能问题上搞选边站队、阵营对抗，主张各方共同维护人工智能全球治理的开放包容。",
