   "summary": "8月19日乌国家反腐败局搜查总统办公室副主任穆德拉住所，涉洗钱约1.5亿格里夫纳，泽连斯基同日签署解职令；乌最高拉达任命赫马拉为国防部长、瑟比加为外长，标志内阁重组结束。",
