   "summary": "8月25日大消费板块盘中持续活跃，零售、食品饮料、旅游方向走强，中百集团封涨停，上海九百、凯撒旅业、三峡旅游、华天酒店涨停；国家统计局数据显示1-7月可穿戴智能设备零售额增超1倍，7月具身智能机器人销售额增95.1%。",
   "decision": "消费板块估值处历史低位、业绩兑现，若招联有消费场景金融布局可顺势加强合作；但板块轮动快，避免盲目追高。",
