   "summary": "美国总统特朗普宣布自2027年1月1日起，将加拿大所有汽车、卡车、零部件和钢铁关税提高至50%。加拿大总理卡尼称不惊讶但拒绝接受附庸地位，美加谈判自7月启动后多次反复，加方曾于8月21日暂停谈判。",
   "decision": "北美贸易摩擦升温或扰动全球汽车与金属供应链，招联需关注出口型制造客户的订单与还款稳定性。",
