   "summary": "伴随楼市新政红利释放，上海外环外改善型楼盘热度传导。「沪八条」新政落地首个周末，青浦徐泾板块改善盘宝业·虹桥国展里二批次64套房源快速清盘，为近10天内上海第三个开盘售罄楼盘。",
