   "summary": "周一A股震荡调整，上证指数报3882.01点跌0.59%，深成指跌2.13%，创业板指跌3.21%，沪深两市成交2.01万亿元较上日放量1282亿，全市场近4000只个股下跌。贵金属、煤炭开采、保险等板块涨幅居前，生物制品、元件、医疗服务跌幅居前。",
