   "summary": "国常会部署普及推广新一代智能终端、培育智慧城市与智能制造等高价值场景。分析认为终端是数据采集与人机交互的重要载体，大规模普及可反向牵引芯片、软件、操作系统全链条迭代，并撬动社会资本加大对新型基础设施投入。",
   "decision": "智能终端与新型基建投资加码，利好数字消费与物联网场景，招联可借势拓展智能家居、数码分期等消费金融品类。",
