   "summary": "《上海市加快推进新型工业化构建现代化产业体系「十五五」规划》提出构建「2+3+6+6」现代化产业体系，市级聚焦10条重点产业链，做强新一代电子信息、智能网联新能源汽车、高端装备等万亿级集群，新增打造集成电路、生物医药、人工智能三个万亿级产业集群。",
   "decision": "上海产业地图明确新质生产力方向，招联在长三角的科技型小微与科创企业金融服务可对标三大万亿赛道布局。",
