   "title": "截至7月底我国电动汽车充电基础设施达2368.3万个 同比增41.9%",
   "summary": "截至2026年7月底，我国电动汽车充电基础设施总数达2368.3万个，同比增长41.9%。同时北斗加速走进大众消费，智能手机、智能穿戴、车载终端等北斗定位已基本实现标配。",
