   "summary": "宏观周报（8/24）显示，7月工业、消费、投资均弱于预期：工业增加值同比增4.5%（较6月回落），社零仅增0.6%，汽车及地产相关耐用品拖累明显；固定资产投资累计降6.7%，地产、基建、制造业及民间投资同步承压。政策端进一步向稳投资倾斜。",
   "decision": "内需走弱叠加地产疲软，消费金融需求端承压；招联资产投放宜聚焦高景气场景、控制敞口。",
