   "summary": "上海8月20日六部门联合发布《关于优化本市房地产政策措施的通知》自8月21日起施行，涵盖公积金提取、住房信贷、以旧换新补贴、房票安置、收购二手住房5方面8项措施；首套商贷首付统一15%，外环外二套首付降至15%，“以旧换新”最高补贴8万元。",
