   "title": "光子计算突破：室温下实现微型激光器自发同步",
   "summary": "英国南安普敦大学领衔的国际团队首次在室温下实现多个微型激光器自发同步，形成相干且可重构的光源。该研究可能成为迈向成本更低、可重构且更易普及的光子计算技术的第一步，相关论文发表于《自然-通讯》。",
   "decision": "光子计算若落地将重塑AI算力格局，长期看有望拉低推理成本，招联做AI中台规划时应预留架构升级空间。",
