   "summary": "北京亦庄正式发布《「AI4Chip」人工智能赋能集成电路产业跨越式发展行动计划（2026—2028年）》，系全国首个AI4Chip专项政策。目标到2028年经开区基本建成集成电路产业AI融合发展体系，培育3—5家具有国际影响力的AI4Chip生态型领军企业。",
