   "summary": "据台媒《经济日报》报道，半导体硅晶圆市场出现三年多以来首次大幅涨价，覆盖12英寸、8英寸和6英寸全尺寸规格，涨幅约10%。AI算力需求爆发推高先进逻辑与存储半导体需求，12英寸硅晶圆供应紧张，带动成熟制程产能利用率提升。",
   "decision": "硅晶圆涨价将沿芯片产业链传导，招联在数码3C分期定价与供应链金融授信时需预留上游成本波动。",
