   "summary": "8月19日朱雀三号遥二运载火箭在东风商业航天创新试验区点火升空，将鸿鹄03星准确送入预定轨道，改写我国商业航天格局。完成突破的是民营航天企业蓝箭航天，标志民营力量在运载与组网能力上迈上新台阶。",
   "decision": "商业航天降本将带动卫星互联网与遥感数据普及，为招联偏远地区组网、资产监测提供新基础设施选项。",
