   "title": "央企6G推进会：公开6G专利5300多件",
   "summary": "国务院国资委召开中央企业6G未来产业推进会，要求央企补齐技术短板、加强基础理论和关键器件创新。自2023年实施未来产业启航行动以来，央企联合体公开6G专利5300多件，在卫星终端与基站核心设备研发上取得新突破。",
