   "summary": "工信部数据显示，2025年我国卫星导航产业总体产值达6290亿元，同比增长9.24%；截至2025年底，国产北斗兼容型芯片及模块累计出货量接近26亿片，各类北斗功能终端产品社会总保有量超22亿台/套。2026年上半年国内市场手机超98%支持北斗定位。",
   "decision": "北斗高渗透为位置金融、保险定损、物流风控提供底层能力，招联可探索基于高精度定位的信贷与反欺诈应用。",
