   "summary": "SpaceX计划在明年第四季度发射首批搭载NVIDIA芯片的AI卫星，2028年推动更大规模部署，采用面向轨道环境优化的Vera Rubin NVL72系统；轨道数据中心的设想希望利用空间电力与散热拓展算力供给，但发射成本与可靠性尚未量产验证。",
