   "summary": "8月17—23日全球AI大模型总调用量达93.3万亿Token，环比增长23.9%；其中中国AI大模型周调用量40.48万亿Token，环比增9.88%。全球调用量排名前五中中国大模型占据四席，DeepSeek-V4-Flash正式版连续三周位居第一。",
   "decision": "国产大模型调用量领先，印证国内AI应用生态活跃，招联可优先选用国产模型以兼顾合规与成本。",
