   "summary": "受台风「紫檀」影响广西多地遭遇强降雨并升级发布洪水红色预警。国家防减救灾委、应急管理部针对洪涝灾害对广西启动国家四级救灾应急响应并派工作组；发改委紧急安排中央预算内投资5000万元支持灾后应急恢复。",
   "decision": "灾后重建带来基建与民生修复需求，招联可关注广西区域小微商户还款缓冲与复工复产金融支持机会。",
