   "summary": "8月24日上午今年第21号台风「艾莎尼」生成，6天内4个台风接连生成，系今年南海和西北太平洋首次「四台共舞」。中央气象台24日18时发布台风黄色预警，中国气象局升级调整重大气象灾害（台风、暴雨、强对流）应急响应为三级。",
   "decision": "极端天气频发，招联华南、华东区域客户还款与外访作业需建立极端天气应急预案，家庭出行也建议暂缓沿海行程。",
