   "summary": "福建省气象台25日14时将“暴雨预警”提升为一级，省防指将防汛应急响应提升至二级；龙岩市新罗区发布防汛动员令，自8时起于重点区域实行停工、停产、停课、休市“三停一休”，各企业事业单位员工弹性上班、人不出门车不上路。",
   "decision": "闽粤赣强降雨致局部停摆，若家人或业务涉及上述区域需提前沟通；预产期临近，福建籍亲友联络与备产物资物流建议留足余量。",
