   "title": "[海外] 新西兰拟立法禁止未满16岁青少年使用社交媒体",
   "summary": "新西兰拟立法禁止13岁及以下儿童使用社交媒体和网络游戏平台，并讨论将限制年龄提高至16岁。该动向与多国加强对未成年人网络保护的趋势一致，引发关于数字素养与家庭监管责任的讨论。",
   "decision": "未成年人网络保护趋严是全球共识，招联在面向年轻客群的金融产品与内容投放上需强化适龄与防沉迷合规。",
