   "summary": "住房城乡建设部数据显示，今年上半年各地新开工建设口袋公园2800多个、城市绿道2450公里，改造提升城市公园绿地约7500公顷，公园绿地开放共享水平持续提升，轮换开放草坪约2.48万公顷。",
