   "title": "深圳保租房认租火爆：25320户抢460套约55:1",
   "summary": "深圳宝安区今年首批面向个人配租的保障性租赁住房认租结果出炉，共25320户家庭提交申请，房源仅460套，供需比约55:1。公证摇号安排已公布，后续将按审核结果与摇号顺序确定选房名单。",
   "decision": "一线保障性租赁住房供需极紧，反映新市民居住成本高，招联在深圳可围绕租房场景设计合规的分期与押金贷产品。",
