   "title": "全国推广去世亲人存款查询便民举措",
   "summary": "多地推进已故存款人小额存款查询与提取便利化，通过跨部门信息共享减少继承人证明材料，破解「证明你爸是你爸」难题。相关便民服务已在更多地区落地，降低群众办事成本。",
