   "summary": "部分民办高校试点允许学生「带着宠物上学」，在校内设置专门寄养区并明确宠物不得带入宿舍。校方称旨在缓解学生情感陪伴需求与心理压力，相关安排引发关于校园管理与责任边界的讨论。",
   "decision": "校园养宠趋势反映年轻群体情感消费升温，招联在校园金融与年轻客群运营中可关注宠物经济相关服务触点。",
