   "summary": "辽宁省丹东市中级人民法院一审公开宣判北京大学原党委常委、副校长任羽中受贿案，查明其2006年至2025年间非法收受财物共计3195万余元，以受贿罪判处有期徒刑八年，罚金二百六十万元，受贿财物及孳息被依法追缴上缴国库。",
