   "summary": "针对河北张家口康保县部分白菜收购商违规使用甲醛溶液保鲜一事，国务院食安办、农业农村部、市场监管总局第一时间指导属地调查核实、依法从严从快处置，追查涉事白菜流向并组织各地开展易腐蔬菜专项抽检。北京新发地市场全链条溯源排查显示问题白菜未流入。",
   "decision": "食品安全事件频发，家庭采购生鲜宜选正规渠道；妻临产在即，食材安全更需留意，关注后续抽检通报。",
