   "summary": "8月23日凌晨凤庆县凤山镇遭遇持续强降雨，安石村诱发泥石流（2人失联）、水箐村诱发滑坡（4人失联）。截至17时，水箐村2名失联人员已找到、确认无生命体征，其余失联人员搜救仍在进行；县里启动Ⅲ级应急响应。",
