   "summary": "中央气象台8月20日发布暴雨蓝色预警，提醒海南、广东、广西、福建、浙江、上海、江苏、山东、黑龙江等地防范；8月21日山东半岛、广西西南部、广东南部沿海、海南、台湾岛等地部分地区有暴雨或大暴雨，伴随短时强降水与雷暴大风。",
