   "title": "今年第18号台风“沙德尔”生成，未来最强或达超强台风级",
   "summary": "今年第18号台风“沙德尔”（热带风暴级）于8月19日上午在西北太平洋生成，中心最大风力8级，将向北偏西移动、强度逐渐增强，未来5天对我国海域暂无影响；受其外围与季风影响，上海等地近期多阵性降雨、风力较大。",
   "decision": "台风季叠加汛期，沿海地区需防灾害；家庭出行与探亲安排宜避开强风雨时段，关注气象预警动态。",
