   "summary": "受热带扰动影响，8月19日至21日广东南部、广西南部、海南岛、台湾岛等地部分地区有大到暴雨、局地大暴雨；华北、内蒙古中东部、东北多阵雨或雷阵雨，局地伴雷暴大风，需警惕山洪、滑坡、泥石流等次生灾害。",
   "decision": "华南与华东沿海强降雨持续，关注对物流、出行与线下消费场景的短期扰动。",
