   "summary": "安徽三伏持续至8月23日，南部连日高温闷热，户外作业工友注意：今年高温津贴涨至25元/天，单位只发消暑饮料不发现金属违规，可向人社部门举报；另提醒猪肉带电子溯源码、退休长辈8月底前完成养老资格认证。",
