   "summary": "截至8月24日，2026年8月全国电影总票房突破50亿元，《欢迎来龙餐馆》《蜘蛛侠：崭新之日》《八仙！》位列前三；其中《欢迎来龙餐馆》上映15天累计16.46亿、豆瓣8.7分，官宣9月起陆续登陆中国香港、中国澳门、澳新、东南亚及日韩等地。",
   "decision": "暑期档与文化消费强劲，反映服务消费活力；与招联消费金融场景（票务分期、文娱消费）可形成获客联动，但属轻度关联。",
