   "summary": "2026年暑期档以总票房115亿元收官，连续44天单日票房过亿，观影人次和放映场次双双刷新历史纪录；《功夫女足》以23.09亿居档期冠军，《八仙！》17.58亿第二，《欢迎来龙餐馆》16.46亿第三且仍在冲高。",
   "decision": "服务消费（影视文旅）持续复苏，印证内需韧性；招联可借文娱消费热度探索场景金融，但需控制与主业无关的分散投入。",
