   "summary": "8月24日沈腾领衔主演的《欢迎来龙餐馆》累计票房突破16亿元，叠加《飞驰人生3》44.2亿，沈腾2026年度个人总票房突破60亿；猫眼数据显示其主演电影总票房已破429亿，位列中国演员之首，影片口碑升至8.7分。",
