   "summary": "24家文学刊物联合发布声明，指出AI生成内容滋生大量伪作者与署名混乱，明确对使用AI代写投稿者一经查实永不采用，呼吁维护原创生态与学术诚信。该声明引发关于AI与创作边界的广泛讨论。",
